import pandas as pd
import numpy as np

# Load the data
energy_data = pd.read_csv('getisord_2021_energy.csv')
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Create a dictionary to store the neighbors for each borough
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = [row['neighbor']]
    else:
        neighbors[row['borough']].append(row['neighbor'])

# Function to calculate the combined total of a borough and its neighbors
def calculate_combined_total(borough):
    combined_total = energy_data.loc[energy_data['borough'] == borough, 'Energy_value'].values[0]
    for neighbor in neighbors[borough]:
        combined_total += energy_data.loc[energy_data['borough'] == neighbor, 'Energy_value'].values[0]
    return combined_total

# Calculate the combined totals for each borough
combined_totals = {}
for borough in energy_data['borough']:
    if pd.notna(energy_data.loc[energy_data['borough'] == borough, 'Energy_value'].values[0]):
        combined_totals[borough] = calculate_combined_total(borough)

# Calculate the citywide average of the combined totals
citywide_average = np.mean(list(combined_totals.values()))

# Calculate the standard deviation of the combined totals
std_dev = np.std(list(combined_totals.values()))

# Calculate the z-scores for each borough
z_scores = {}
for borough, total in combined_totals.items():
    z_scores[borough] = (total - citywide_average) / std_dev

# Identify hot and cold spots
hot_spots = {borough: z_score for borough, z_score in z_scores.items() if abs(z_score) > 1.96}
cold_spots = {borough: z_score for borough, z_score in z_scores.items() if abs(z_score) > 1.96 and z_score < 0}

# Print the results
data_points_used = len(combined_totals)
results = []
for borough, z_score in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z_score}, gi_value={z_score})")
for borough, z_score in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z_score}, gi_value={z_score})")
print(f"data_points_used = {data_points_used}")
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
